    "contentHtml": "<header class=\"md-article-header\">\r\n                <div class=\"md-article-title\" id=\"article-title\">FAQ</div>\r\n\r\n                <div class=\"read-info\">1 min</div>\r\n\r\n                <div class=\"created-info\">Criado por Thomaz Queiroz em 23/07/2025 15:13</div>\r\n                    <div class=\"updated-info\">Atualizado por Thomaz Queiroz em 23/07/2025 15:30</div>\r\n\r\n            </header>\r\n                <div class=\"article-content fr-view\"><h2 data-end=\"115\" data-start=\"86\" id=\"isPasted\"><span style=\"font-size: 18px;\"><strong>Perguntas Frequentes (FAQ)</strong></span></h2><p data-end=\"360\" data-start=\"117\"><span style=\"font-size: 18px;\">Nesta se&ccedil;&atilde;o, voc&ecirc; encontrar&aacute; respostas para as d&uacute;vidas mais recorrentes sobre o funcionamento do sistema Conciliador Cont&aacute;bil. Os t&oacute;picos abordam desde importa&ccedil;&otilde;es e exclus&otilde;es de lan&ccedil;amentos, at&eacute; atualiza&ccedil;&atilde;o de vers&atilde;o, backups, layouts e mais.</span></p><p data-is-only-node=\"\" data-is-last-node=\"\" data-end=\"596\" data-start=\"362\"><span style=\"font-size: 18px;\">As respostas detalhadas est&atilde;o organizadas no menu lateral &agrave; esquerda. Recomendamos que navegue pelos t&oacute;picos para encontrar facilmente o que precisa. Essa base foi criada para tornar sua experi&ecirc;ncia no sistema mais pr&aacute;tica e objetiva.</span></p></div>\r\n            <footer class=\"article-footer\">\r\n                <!-- Attachments -->\r\n\r\n                <!-- Rating -->\r\n\r\n                <!-- Related Articles -->\r\n\r\n                <!-- AccessHistory -->\r\n                <div class=\"panel panel-default\" id=\"last-visited-articles\" style=\"\">\r\n                    <div class=\"panel-heading\">&#218;ltimos artigos visitados</div>\r\n                    <ul class=\"list-group\">\r\n                            <li class=\"list-group-item\"><a class=\"kb-article-to-article-hyperlink\" href=\"https://conciliador-contabil2.movidesk.com/kb/article/545273/primeiros-passos?ticketId=&amp;q=\">Primeiros passos</a></li>\r\n                            <li class=\"list-group-item\"><a class=\"kb-article-to-article-hyperlink\" href=\"https://conciliador-contabil2.movidesk.com/kb/article/545649/cadastro-de-usuarios?ticketId=&amp;q=\">Cadastrar Usu&#225;rios</a></li>\r\n                            <li class=\"list-group-item\"><a class=\"kb-article-to-article-hyperlink\" href=\"https://conciliador-contabil2.movidesk.com/kb/article/545658/empresas?ticketId=&amp;q=\">Cadastrar Empresas</a></li>\r\n                            <li class=\"list-group-item\"><a class=\"kb-article-to-article-hyperlink\" href=\"https://conciliador-contabil2.movidesk.com/kb/article/545660/contabilidade?ticketId=&amp;q=\">Cadastro da Contabilidade</a></li>\r\n                            <li class=\"list-group-item\"><a class=\"kb-article-to-article-hyperlink\" href=\"https://conciliador-contabil2.movidesk.com/kb/article/545661/layouts?ticketId=&amp;q=\">Cadastro de Layouts</a></li>\r\n                    </ul>\r\n                </div>\r\n\r\n            </footer>",
