    "categoryName": "Movimentações",
    "authorId": "usr-fulvio",
    "authorName": "Fulvio Tanure",
    "authorEmail": "fulvio@conciliadorcontabil.com.br",
    "currentStatus": "APPROVED",
    "accessLevel": "ALL",
